package com.bn.aliagent.insight.radar; import static org.junit.jupiter.api.Assertions.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class RadarServiceTest { @Test void mergesSameTenantProblemDimensionsAndWindowButNotAnotherTenant(){var service=new RadarService();var a=service.open("test-a","refund",Map.of("reason","late"),Instant.EPOCH,Instant.EPOCH.plusSeconds(3600),1,2,3);var same=service.open("test-a","refund",Map.of("reason","late"),Instant.EPOCH,Instant.EPOCH.plusSeconds(3600),1,2,3);var other=service.open("test-b","refund",Map.of("reason","late"),Instant.EPOCH,Instant.EPOCH.plusSeconds(3600),1,2,3);assertEquals(a.radarId(),same.radarId());assertNotEquals(a.radarId(),other.radarId());}
 @Test void rejectsIllegalRadarTransition(){var radar=ProblemRadar.open("test-tenant","refund",Map.of(),Instant.EPOCH,Instant.EPOCH.plusSeconds(1),1,1,1);assertThrows(IllegalStateException.class,()->radar.transition(RadarStatus.RESOLVED,"test-operator","未确认直接解决"));assertEquals(RadarStatus.ACKNOWLEDGED,radar.transition(RadarStatus.ACKNOWLEDGED,"test-operator","确认").status());}}
